function inside(pt){return asset()&&pt[0]>=0&&pt[1]>=0&&pt[0]<=asset().width&&pt[1]<=asset().height}
function bounded(pt){return [clamp(pt[0],0,asset().width),clamp(pt[1],0,asset().height)]}
function queueDraw(){if(paintQueued)return;paintQueued=true;requestAnimationFrame(()=>{paintQueued=false;draw()})}
function draw(){if(screen!=='workspace')return;const ctx=$('planCanvas').getContext('2d'),dpr=Math.min(window.devicePixelRatio||1,3);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,size.w,size.h);if(!image||!asset())return;ctx.save();ctx.translate(view.x,view.y);ctx.scale(view.s,view.s);ctx.shadowColor='#23453913';ctx.shadowBlur=28/view.s;ctx.shadowOffsetY=5/view.s;ctx.fillStyle='white';ctx.fillRect(0,0,asset().width,asset().height);ctx.shadowColor='transparent';ctx.drawImage(image,0,0,asset().width,asset().height);if(showOverlay){for(const o of floor().items){if(draft?.id===o.id)continue;boxDraw(ctx,o,o.id===selected)}}if(draft)boxDraw(ctx,draft,true,true);if(gesture?.kind==='rect'){const r=rectBetween(gesture.start,gesture.end);boxDraw(ctx,{rect:r,label:'松开鼠标，补充对象',type:'',source:'manual'},true,true)}ctx.restore()}
function boxDraw(ctx,o,sel=false,temp=false){const [x,y,w,h]=o.rect,c=color(o),lw=(sel?1.8:1.15)/view.s;ctx.fillStyle=sel?'#638fb714':o.status==='pending'?'#edbf6320':'#59a88710';ctx.fillRect(x,y,w,h);ctx.strokeStyle=c;ctx.lineWidth=lw;ctx.setLineDash(o.status==='pending'?[5/view.s,3/view.s]:[]);ctx.strokeRect(x,y,w,h);ctx.setLineDash([]);const label=(o.label||o.type||'新对象')+(o.status==='pending'?' · 待复核':'');ctx.font=`${10/view.s}px -apple-system,BlinkMacSystemFont,"PingFang SC","Noto Sans CJK SC",sans-serif`;const tw=ctx.measureText(label).width+12/view.s,ty=Math.max(0,y-22/view.s);ctx.fillStyle='#ffffffef';ctx.strokeStyle=c+'66';ctx.lineWidth=.6/view.s;ctx.beginPath();ctx.roundRect(x,ty,tw,18/view.s,3/view.s);ctx.fill();ctx.stroke();ctx.fillStyle=c;ctx.textBaseline='middle';ctx.fillText(label,x+6/view.s,ty+9/view.s);if(sel){for(const [a,b] of [[x,y],[x+w,y],[x,y+h],[x+w,y+h]]){ctx.fillStyle='white';ctx.fillRect(a-3/view.s,b-3/view.s,6/view.s,6/view.s);ctx.strokeStyle=c;ctx.strokeRect(a-3/view.s,b-3/view.s,6/view.s,6/view.s)}}}
function rectBetween(a,b){return [Math.min(a[0],b[0]),Math.min(a[1],b[1]),Math.abs(b[0]-a[0]),Math.abs(b[1]-a[1])]}
function hit(pt){const items=showOverlay?[...floor().items].sort((a,b)=>a.rect[2]*a.rect[3]-b.rect[2]*b.rect[3]):[];return items.find(o=>pt[0]>=o.rect[0]&&pt[0]<=o.rect[0]+o.rect[2]&&pt[1]>=o.rect[1]&&pt[1]<=o.rect[1]+o.rect[3])}
function handleHit(pt){if(!draft)return null;const [x,y,w,h]=draft.rect,pts=[[x,y],[x+w,y],[x,y+h],[x+w,y+h]];const k=pts.findIndex(q=>Math.hypot(q[0]-pt[0],q[1]-pt[1])*view.s<=9);return k<0?null:k}
function pointerDown(e){if(e.button!==0||!image)return;const q=point(e);$('planCanvas').focus({preventScroll:true});if(tool==='pan'||space){gesture={kind:'pan',x:e.clientX,y:e.clientY,vx:view.x,vy:view.y};$('planCanvas').setPointerCapture(e.pointerId);return}if(job)return;if(draft){const k=handleHit(q);const r=draft.rect;if(k!==null){gesture={kind:'resize',corner:k,orig:[...r]};$('planCanvas').setPointerCapture(e.pointerId);return}if(q[0]>=r[0]&&q[0]<=r[0]+r[2]&&q[1]>=r[1]&&q[1]<=r[1]+r[3]){gesture={kind:'move',start:q,orig:[...r]};$('planCanvas').setPointerCapture(e.pointerId);return}guardDraft(()=>{selected=null;queueDraw()});return}if(!inside(q)){selected=null;queueDraw();return}if(tool==='rect'){gesture={kind:'rect',start:bounded(q),end:bounded(q)};$('planCanvas').setPointerCapture(e.pointerId);e.preventDefault()}else{const o=hit(q);if(o)selectObject(o.id);else{selected=null;queueDraw()}}}
function pointerMove(e){if(!asset())return;const q=point(e);$('coordInfo').textContent=inside(q)?`原图 ${Math.round(q[0])}, ${Math.round(q[1])} px`:'原图坐标 —';if(!gesture)return;if(gesture.kind==='pan'){view.x=gesture.vx+e.clientX-gesture.x;view.y=gesture.vy+e.clientY-gesture.y;positionEditor()}else if(gesture.kind==='rect'){gesture.end=bounded(q)}else if(gesture.kind==='move'){const r=gesture.orig;draft.rect=[clamp(r[0]+q[0]-gesture.start[0],0,asset().width-r[2]),clamp(r[1]+q[1]-gesture.start[1],0,asset().height-r[3]),r[2],r[3]];updateRectText();positionEditor()}else if(gesture.kind==='resize'){const [x,y,w,h]=gesture.orig;const anchors=[[x+w,y+h],[x,y+h],[x+w,y],[x,y]];const r=rectBetween(anchors[gesture.corner],bounded(q));if(r[2]>=8&&r[3]>=8)draft.rect=r;updateRectText();positionEditor()}queueDraw()}
function pointerUp(e,cancel=false){if(!gesture)return;const g=gesture;gesture=null;try{$('planCanvas').releasePointerCapture(e.pointerId)}catch(_){}if(cancel){if((g.kind==='move'||g.kind==='resize')&&draft)draft.rect=g.orig;queueDraw();return}if(g.kind==='rect'){const r=rectBetween(g.start,g.end);if(r[2]<8||r[3]<8){toast('框太小了，请至少框选 8 × 8 个原图像素。');queueDraw();return}if(floor().items.length>=limits.objects){toast('每层最多保存 200 个标注。',true);queueDraw();return}draft={id:uid('M'),type:'设备',label:'',note:'',rect:r.map(v=>Math.round(v*10)/10),source:'manual',status:'confirmed'};draftOriginal=null;selected=draft.id;showEditor();event(p(),'annotation.drafted','拉框补充（未保存）',{floor:activeFloor,rect:draft.rect})}queueDraw()}
function selectObject(id,fid=activeFloor){if(job){toast('流程演示中，完成或取消后可编辑。');return}guardDraft(async()=>{if(fid!==activeFloor){activeFloor=fid;p().currentFloor=fid;await loadFloor(true)}const o=floor()?.items.find(x=>x.id===id);if(!o)return;draft=clone(o);draftOriginal=clone(o);selected=id;closePop();showOverlay=true;$('overlayBtn').setAttribute('aria-pressed','true');$('overlayBtn').classList.add('active');showEditor();queueDraw();if(drawer)renderDrawer()})}
function showEditor(){const d=draft;if(!d)return;const categories=['墙体','门','窗','楼梯','卫生间','机房','机柜区','办公室','房间','设备','其他'];const extra=categories.includes(d.type)?[]:[d.type];$('annotationEditor').innerHTML=`<div class="form-head"><div><strong>${draftOriginal?'复核图上对象':'补充未识别的对象'}</strong><div class="tiny">${draftOriginal?.source==='preset'?'预设候选 · 不是模型检测':draftOriginal?'人工补充':'新框 · 尚未保存'}</div></div><button class="iconbtn" id="cancelAnnotation" aria-label="关闭补框表单">${ic('close')}</button></div><form id="annotationForm"><div class="form-body"><div class="form-row"><div class="field"><label for="objectType">对象类型</label><select id="objectType">${[...extra,...categories].map(t=>`<option ${t===d.type?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label for="objectName">名称 <span class="muted">可选</span></label><input id="objectName" maxlength="60" placeholder="例如：楼梯平台" value="${esc(d.label)}"></div></div><div class="field"><label for="objectNote">补充说明</label><textarea id="objectNote" maxlength="500" placeholder="只描述图中已有内容，不重新安排房间。">${esc(d.note)}</textarea></div></div><p id="rectInfo" class="form-hint"></p><div class="form-actions">${draftOriginal?`<button class="iconbtn" type="button" id="deleteAnnotation" title="仅删除标注，不修改原图" aria-label="删除标注">${ic('trash')}</button>`:'<span class="tiny muted">拖动框角可调整</span>'}<div class="flex" style="gap:6px"><button class="btn" type="button" id="cancelForm">取消</button><button class="btn primary" type="submit" id="saveAnnotation">${ic('check')}${draftOriginal?'确认并保存':'保存补充'}</button></div></div></form>`;$('annotationEditor').classList.remove('hidden');$('annotationForm').onsubmit=e=>{e.preventDefault();saveAnnotation()};$('objectType').onchange=()=>{draft.type=$('objectType').value};$('objectName').oninput=()=>{draft.label=$('objectName').value;queueDraw()};$('objectNote').oninput=()=>{draft.note=$('objectNote').value};$('cancelAnnotation').onclick=$('cancelForm').onclick=()=>cancelDraft(true);if($('deleteAnnotation'))$('deleteAnnotation').onclick=deleteAnnotation;updateRectText();positionEditor();requestAnimationFrame(()=>{(draftOriginal?$('saveAnnotation'):$('objectType')).focus({preventScroll:true})})}
function updateRectText(){if(draft&&$('rectInfo'))$('rectInfo').textContent=`原图范围 ${draft.rect.map(v=>Math.round(v)).join(' / ')} px · 仅添加标注`}
function positionEditor(){if(!draft||$('annotationEditor').classList.contains('hidden')||size.w<641)return;const r=draft.rect,boxEl=$('annotationEditor'),w=boxEl.offsetWidth||280,h=boxEl.offsetHeight||320;let x=view.x+(r[0]+r[2])*view.s+18;if(x+w>size.w-18)x=view.x+r[0]*view.s-w-18;if(x<75)x=size.w-w-20;let y=view.y+r[1]*view.s-12;x=clamp(x,75,Math.max(75,size.w-w-16));y=clamp(y,47,Math.max(47,size.h-h-60));boxEl.style.left=x+'px';boxEl.style.right='auto';boxEl.style.top=y+'px'}
